  expect(watchesAfterReload).toBeGreaterThan(0);

  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.getByRole("button", { name: "Hold to end walk" }).click();
  await page.getByRole("button", { name: "Confirm end walk" }).click();
