async function installResumableWatch(page: Page): Promise<void> {
  await page.addInitScript(() => {
    const timers = new Map<number, number>();
    let nextId = 1;
    let generation = 0;
    Object.defineProperty(navigator, "wakeLock", {
      configurable: true,
      value: {
        request: async () => {
          return {
            release: async () => undefined,
            addEventListener() {
              return undefined;
            },
            removeEventListener() {
              return undefined;
            },
          };
        },
      },
    });
    navigator.geolocation.watchPosition = (success) => {
      const id = nextId;
      nextId += 1;
      const origin = 1_700_000_000_000 + generation * 20_000;
      generation += 1;
      const samples = [
        { latitude: 12.9716, longitude: 77.5946, accuracy: 8, timestamp: origin },
        { latitude: 12.972, longitude: 77.595, accuracy: 10, timestamp: origin + 1500 },
      ];
      let index = 0;
      const timer = window.setInterval(() => {
        const next = samples[index];
        index += 1;
        if (!next) {
          window.clearInterval(timer);
          return;
        }
        success({
          coords: {
            latitude: next.latitude,
            longitude: next.longitude,
            accuracy: next.accuracy,
            altitude: null,
            altitudeAccuracy: null,
            heading: null,
            speed: null,
            toJSON() {
              return this;
            },
          },
          timestamp: next.timestamp,
          toJSON() {
            return this;
          },
        });
      }, 20);
      timers.set(id, timer);
      return id;
    };
    navigator.geolocation.clearWatch = (id) => {
      const timer = timers.get(id);
      if (timer !== undefined) window.clearInterval(timer);
      timers.delete(id);
    };
  });
}

